package com.ofss.entity;
import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.OffsetDateTime;
@Entity @Table(name="APR_WORKFLOWS",uniqueConstraints=@UniqueConstraint(name="UK_APR_PAYMENT",columnNames="PAYMENT_ID")) public class ApprovalWorkflow {
@Id @GeneratedValue(strategy=GenerationType.SEQUENCE,generator="approval_workflow_seq") @SequenceGenerator(name="approval_workflow_seq",sequenceName="APR_WORKFLOWS_SEQ",allocationSize=50) @Column(name="WORKFLOW_ID") private Long id;
@Column(name="PAYMENT_ID",nullable=false) private Long paymentId; @Column(name="REQUESTER_ID",nullable=false) private Long requesterId; @Column(name="PAYMENT_AMOUNT",nullable=false,precision=15,scale=2) private BigDecimal paymentAmount; @Enumerated(EnumType.STRING) @Column(name="RISK_BAND",nullable=false) private RiskBand riskBand; @Enumerated(EnumType.STRING) @Column(name="REQUIRED_LEVEL",nullable=false) private ApprovalLevel requiredLevel; @Enumerated(EnumType.STRING) @Column(name="STATUS",nullable=false) private ApprovalStatus status; @Column(name="ASSIGNED_APPROVER_ID") private Long assignedApproverId; @Column(name="DECIDED_BY") private Long decidedBy; @Lob @Column(name="REMARK") private String remark; @Column(name="DUE_AT",nullable=false) private OffsetDateTime dueAt;
@PrePersist void init(){if(status==null)status=ApprovalStatus.PENDING_APPROVAL;} public Long getId(){return id;} public Long getPaymentId(){return paymentId;} public void setPaymentId(Long v){paymentId=v;} public Long getRequesterId(){return requesterId;} public void setRequesterId(Long v){requesterId=v;} public void setPaymentAmount(BigDecimal v){paymentAmount=v;} public void setRiskBand(RiskBand v){riskBand=v;} public ApprovalLevel getRequiredLevel(){return requiredLevel;} public void setRequiredLevel(ApprovalLevel v){requiredLevel=v;} public ApprovalStatus getStatus(){return status;} public void setStatus(ApprovalStatus v){status=v;} public void setAssignedApproverId(Long v){assignedApproverId=v;} public Long getDecidedBy(){return decidedBy;} public void setDecidedBy(Long v){decidedBy=v;} public String getRemark(){return remark;} public void setRemark(String v){remark=v;} public OffsetDateTime getDueAt(){return dueAt;} public void setDueAt(OffsetDateTime v){dueAt=v;}
}
